do $guard$ declare f record; begin for f in select p.oid::regprocedure as signature,pg_get_functiondef(p.oid) as definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname ~ '^admin_' loop if position('perform public.assert_is_admin();' in f.definition)=0 then execute regexp_replace(f.definition,'\mbegin\M',E'begin\n perform public.assert_is_admin();','i'); end if; execute format('revoke execute on function %s from public,anon',f.signature); end loop; end $guard$;
